import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

/* ================== Animations ================== */
const styleSheet = document.createElement("style");
styleSheet.textContent = `
  @keyframes slideIn {
    from { transform: translateX(100%); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
  }
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;
document.head.appendChild(styleSheet);

function ManageEvaluationCriteriaPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [criteria, setCriteria] = useState([]);
    const [study, setStudy] = useState(null); // 🔥 StudyType için
    const [newCriterion, setNewCriterion] = useState({
        name: "",
        description: "",
        scaleType: "",
        scaleRange: ""
    });
    const [loading, setLoading] = useState(false);
    const [toasts, setToasts] = useState([]);

    /* ================== Toast ================== */
    const showToast = (message, type = "success") => {
        const id = Date.now();
        setToasts((prev) => [...prev, { id, message, type }]);
        setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3000);
    };

    /* ================== Load STUDY + CRITERIA ================== */
    useEffect(() => {
        const loadAll = async () => {
            try {
                setLoading(true);

                // 🔥 1) Study fetch
                const sRes = await fetch(`http://localhost:8080/api/studies/${studyId}`);
                const studyData = await sRes.json();
                setStudy(studyData);

                // 🔥 2) Criteria fetch
                const cRes = await fetch(`http://localhost:8080/api/criteria/study/${studyId}`);
                const criteriaData = await cRes.json();
                setCriteria(criteriaData);

            } catch (err) {
                console.error("Error fetching data:", err);
                showToast("Failed to load study or criteria", "error");
            } finally {
                setLoading(false);
            }
        };

        loadAll();
    }, [studyId]);

    /* ================== ADD CRITERION ================== */
    const handleAdd = async () => {
        if (!newCriterion.name || !newCriterion.scaleType || !newCriterion.scaleRange) {
            showToast("Please fill in all required fields", "error");
            return;
        }

        try {
            const res = await fetch(`http://localhost:8080/api/criteria/create/${studyId}`, {
                method: "POST",
                headers: { "Content-Type": "application/json", "Accept": "application/json" },
                body: JSON.stringify(newCriterion),
            });

            if (!res.ok) throw new Error("Failed to create criterion");

            const created = await res.json();
            setCriteria([...criteria, created]);
            setNewCriterion({ name: "", description: "", scaleType: "", scaleRange: "" });
            showToast("Criterion added successfully!", "success");

        } catch (err) {
            console.error("Error adding criterion:", err);
            showToast("Failed to add criterion", "error");
        }
    };

    /* ================== DELETE CRITERION ================== */
    const handleDelete = async (id) => {
        if (!window.confirm("Are you sure you want to delete this criterion?")) return;

        try {
            const res = await fetch(`http://localhost:8080/api/criteria/${id}`, {
                method: "DELETE",
            });

            if (!res.ok) throw new Error("Failed to delete criterion");

            setCriteria(criteria.filter((c) => c.id !== id));
            showToast("Criterion deleted successfully!", "success");

        } catch (err) {
            console.error("Error deleting criterion:", err);
            showToast("Failed to delete criterion", "error");
        }
    };

    /* ================== COLOR HELPERS ================== */
    const getScaleTypeColor = (type) => {
        switch (type) {
            case "NUMERIC": return { bg: "rgba(59,130,246,0.15)", color: "#60a5fa", border: "rgba(59,130,246,0.4)" };
            case "QUALITATIVE": return { bg: "rgba(168,85,247,0.15)", color: "#c084fc", border: "rgba(168,85,247,0.4)" };
            case "RATING": return { bg: "rgba(250,204,21,0.15)", color: "#fde047", border: "rgba(250,204,21,0.4)" };
            default: return { bg: "rgba(255,255,255,0.1)", color: "#f3f4f6", border: "rgba(255,255,255,0.2)" };
        }
    };

    const getScaleTypeIcon = (type) => {
        switch (type) {
            case "NUMERIC": return "📊";
            case "QUALITATIVE": return "💬";
            case "RATING": return "⭐";
            default: return "📋";
        }
    };

    return (
        <div style={styles.container}>

            {/* Toasts */}
            <div style={styles.toastContainer}>
                {toasts.map((toast) => (
                    <div
                        key={toast.id}
                        style={{
                            ...styles.toast,
                            ...(toast.type === "success"
                                ? styles.toastSuccess
                                : toast.type === "error"
                                    ? styles.toastError
                                    : styles.toastInfo),
                        }}
                    >
                        <span style={styles.toastIcon}>
                            {toast.type === "success" ? "✅" : toast.type === "error" ? "❌" : "ℹ️"}
                        </span>
                        {toast.message}
                    </div>
                ))}
            </div>

            {/* Navbar */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Evaluation Criteria</h2>
                <button style={styles.backButton} onClick={() => navigate(-1)}>← Back</button>
            </div>

            <div style={styles.content}>

                {/* ADD CRITERION */}
                <div style={styles.formCard}>
                    <h2 style={styles.sectionTitle}>➕ Add New Criterion</h2>

                    <div style={styles.formGrid}>
                        <div style={styles.inputGroup}>
                            <label style={styles.label}>Name *</label>
                            <input
                                type="text"
                                value={newCriterion.name}
                                onChange={(e) => setNewCriterion({ ...newCriterion, name: e.target.value })}
                                style={styles.input}
                            />
                        </div>

                        <div style={styles.inputGroup}>
                            <label style={styles.label}>Scale Type *</label>
                            <select
                                value={newCriterion.scaleType}
                                onChange={(e) => setNewCriterion({ ...newCriterion, scaleType: e.target.value })}
                                style={styles.select}
                            >
                                <option value="">Select Type</option>
                                <option value="NUMERIC">📊 Numeric</option>
                                <option value="QUALITATIVE">💬 Qualitative</option>
                                <option value="RATING">⭐ Rating</option>
                            </select>
                        </div>

                        <div style={styles.inputGroup}>
                            <label style={styles.label}>Scale Range *</label>
                            <input
                                type="text"
                                value={newCriterion.scaleRange}
                                onChange={(e) => setNewCriterion({ ...newCriterion, scaleRange: e.target.value })}
                                style={styles.input}
                                placeholder="e.g., 1–5"
                            />
                        </div>

                        <div style={styles.inputGroup}>
                            <label style={styles.label}>Description</label>
                            <input
                                type="text"
                                value={newCriterion.description}
                                onChange={(e) => setNewCriterion({ ...newCriterion, description: e.target.value })}
                                style={styles.input}
                            />
                        </div>
                    </div>

                    <button onClick={handleAdd} style={styles.addButton}>➕ Add Criterion</button>
                </div>

                {/* LIST */}
                <div style={styles.listCard}>
                    <div style={styles.listHeader}>
                        <h2 style={styles.sectionTitle}>📋 Existing Criteria</h2>
                        <span style={styles.countBadge}>{criteria.length}</span>
                    </div>

                    {loading ? (
                        <div style={styles.loadingContainer}>
                            <div style={styles.loader}></div>
                            <p style={styles.loadingText}>Loading...</p>
                        </div>
                    ) : criteria.length === 0 ? (
                        <div style={styles.emptyState}>
                            <div style={styles.emptyIcon}>📭</div>
                            <p>No criteria yet</p>
                        </div>
                    ) : (
                        <div style={styles.criteriaGrid}>
                            {criteria.map((c) => {
                                const t = getScaleTypeColor(c.scaleType);
                                return (
                                    <div key={c.id} style={styles.criterionCard}>

                                        {/* Header */}
                                        <div style={styles.criterionHeader}>
                                            <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                                                <h3 style={styles.criterionName}>{c.name}</h3>

                                                {/* 🔒 Default only if NOT CUSTOM */}
                                                {c.defaultCriterion && study?.studyType !== "CUSTOM" && (
                                                    <span style={styles.defaultBadge}>🔒 Default</span>
                                                )}
                                            </div>

                                            {/* 🗑 Delete only if not default OR type === CUSTOM */}
                                            {(study?.studyType === "CUSTOM" || !c.defaultCriterion) && (
                                                <button
                                                    onClick={() => handleDelete(c.id)}
                                                    style={styles.deleteButton}
                                                >
                                                    🗑
                                                </button>
                                            )}
                                        </div>

                                        {/* Scale Type */}
                                        <span
                                            style={{
                                                ...styles.typeBadge,
                                                background: t.bg,
                                                color: t.color,
                                                border: `1.5px solid ${t.border}`,
                                            }}
                                        >
                                            {getScaleTypeIcon(c.scaleType)} {c.scaleType}
                                        </span>

                                        {c.description && (
                                            <p style={styles.criterionDesc}>{c.description}</p>
                                        )}

                                        <div style={styles.rangeSection}>
                                            <span style={styles.rangeLabel}>Scale Range:</span>
                                            <span style={styles.rangeValue}>{c.scaleRange}</span>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

/* ===================== STYLES ===================== */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #1e293b)",
